reply:
{
  "title": "Engagement Under the Stated Exceptions",
  "setting": "Combatant command; before a proposed engagement; under established ROE.",
  "decider": "The operational commander",
  "agent_recast": false,
  "recast_note": "",
  "agent": "The operational commander",
  "agent_role": "decide",
  "situation": "At a combatant command, an entity remains on the NSL and has not yet been reflected on the JTL. The ordinary route requires a status change and placement on the JTL or RTL before a strike can be approved and executed. The decision point concerns an entity for which a stated exception applies: intelligence confirms military use and a time-sensitive need, or troops are in contact and taking hostile fire from NSEs. Applicable authority remains subject to any express limitation in SecDef-provided supplemental ROE.",
  "question": "What should the operational commander do when a stated exception applies to an entity that has not completed the ordinary NSL status-change and JTL process?",
  "facts": [
    {
      "id": "F1",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Before a strike is approved and executed under the ordinary process, the CCMD must remove the NSE from the NSL and place the entity identification number with the appropriate secondary hostile CATCODE or function code on the JTL or RTL, as appropriate.",
      "spans": [
        "src:f14afcd731ae#p43.4"
      ]
    },
    {
      "id": "F2",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Unless higher authority designates otherwise, only the CCDR or a designated representative may change an entity's status on the NSL.",
      "spans": [
        "src:f14afcd731ae#p43.4"
      ]
    },
    {
      "id": "F3",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Changes to the NSL must be coordinated with Joint Staff Targeting and the appropriate RACs and documented by DTG and reason.",
      "spans": [
        "src:f14afcd731ae#p43.4"
      ]
    },
    {
      "id": "F4",
      "kind": "intelligence",
      "status": "confirmed",
      "fact": "One stated exception applies when intelligence confirms the NSE is used for a military purpose and the need to strike is time sensitive.",
      "spans": [
        "src:f14afcd731ae#p43.6"
      ]
    },
    {
      "id": "F5",
      "kind": "situation",
      "status": "confirmed",
      "fact": "Another stated exception applies when troops are in contact and taking hostile fire from NSEs.",
      "spans": [
        "src:f14afcd731ae#p43.7"
      ]
    },
    {
      "id": "F6",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Under the stated exceptions, the entity need not be reflected on the JTL before it can be engaged.",
      "spans": [
        "src:f14afcd731ae#p43.8"
      ]
    },
    {
      "id": "F7",
      "kind": "authority",
      "status": "confirmed",
      "fact": "Unless expressly limited in SecDef-provided supplemental ROE, operational imperatives and established ROE, including the inherent right and obligation of self-defense, provide authority to engage in the stated exception circumstances.",
      "spans": [
        "src:f14afcd731ae#p43.8"
      ]
    }
  ],
  "options": {
    "O1": {
      "do": "The operational commander authorizes immediate engagement under the applicable exception for the entity.",
      "move": "act",
      "disposition": "authorize",
      "irreversible": true
    },
    "O2": {
      "do": "The operational commander declines immediate engagement and follows the ordinary NSL status-change and JTL process first.",
      "move": "act",
      "disposition": "decline",
      "irreversible": false
    }
  },
  "opposite_pair": [
    "O1",
    "O2"
  ],
  "real_option": "O1",
  "authored_options": [
    "O2"
  ],
  "no_opposite_reason": "",
  "basis_statement": "The governing directive provides authority to engage under the stated exceptions unless SecDef-provided supplemental ROE expressly limits that authority."
}
